    const level = document.getElementById("level-filter");
    const availability = document.getElementById("availability-filter");

    if (search) {
      search.value = "";
    }
    if (dept) {
      dept.value = "all";
    }
    if (level) {
      level.value = "all";
    }
    if (availability) {
      availability.value = "all";
    }

    updateCatalogResults();
  }
