const { chromium } = require('playwright');

(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage({ viewport: { width: 1280, height: 900 } });
  const consoleErrors = [];
  const pageErrors = [];
  page.on('console', msg => { if (msg.type() === 'error') consoleErrors.push(msg.text()); });
  page.on('pageerror', err => pageErrors.push(err.message));

  let failures = 0;
  function check(cond, msg) {
    if (!cond) { console.log('FAIL: ' + msg); failures++; } else console.log('PASS: ' + msg);
  }
  async function activeInfo() {
    return page.evaluate(() => {
      const el = document.activeElement;
      return el ? { tag: el.tagName, id: el.id, text: (el.textContent || '').trim().slice(0, 60) } : null;
    });
  }

  await page.goto('http://localhost:8765/index.html');
  await page.waitForTimeout(300);
  check(await page.locator('h1').innerText() === 'Plan your next semester with confidence', 'home loads');
  check(await page.locator('.nav-list a[aria-current="page"]').getAttribute('data-route') === '#/home', 'home aria-current');
  check(await page.title() === 'Home | Northgate University Course Registration', 'home title');

  // Skip link first focusable
  await page.keyboard.press('Tab');
  let a = await activeInfo();
  check(a && a.text.includes('Skip to main content'), 'skip link is first focusable');
  await page.keyboard.press('Enter');
  await page.waitForTimeout(100);
  a = await activeInfo();
  check(a && a.tag === 'MAIN', 'skip link focuses main');

  // Navigate catalog
  await page.locator('.nav-list a[data-route="#/catalog"]').click();
  await page.waitForTimeout(150);
  check(await page.locator('h1').innerText() === 'Course catalog', 'catalog loads');
  check((await activeInfo()).tag === 'H1', 'catalog focus moved to h1');
  check(await page.locator('#course-list > li').count() === 16, '16 course cards');
  check((await page.locator('#catalog-count').innerText()).includes('16'), 'count 16');

  // Search
  await page.locator('#course-search').fill('biology');
  await page.waitForTimeout(150);
  check(await page.locator('#course-list > li').count() === 2, 'search biology -> 2');
  check((await page.locator('#catalog-count').innerText()).startsWith('2 courses'), 'search count updated');
  check((await page.locator('#app-status').innerText()).includes('2 courses'), 'search announced in status region');
  await page.locator('[data-action="reset-filters"]').click();
  await page.waitForTimeout(100);
  check(await page.locator('#course-list > li').count() === 16, 'reset filters');

  // Filters
  await page.selectOption('#dept-filter', 'CSE');
  await page.waitForTimeout(100);
  check(await page.locator('#course-list > li').count() === 3, 'dept filter CSE');
  await page.selectOption('#level-filter', '400');
  await page.waitForTimeout(100);
  check(await page.locator('#course-list > li').count() === 1, 'level 400 with CSE');
  await page.selectOption('#availability-filter', 'full');
  await page.waitForTimeout(100);
  check(await page.locator('#course-list > li').count() === 1, 'full CSE 400 course');
  await page.locator('[data-action="reset-filters"]').click();

  // Register from card
  await page.locator('button[aria-label="Register for CSE 320"]').click();
  await page.waitForTimeout(200);
  check(await page.locator('h1').innerText() === 'Course registration', 'registration loads');
  check(await page.locator('#course').inputValue() === 'CSE320', 'course preselected');
  check(await page.locator('#full-name').inputValue() === 'Jordan Ellis', 'name prefilled');
  check(await page.locator('#email').inputValue() === 'jordan.ellis@northgate.edu', 'email prefilled');
  check(await page.locator('#student-id').inputValue() === '20261457', 'student ID prefilled');
  check(await page.locator('#program').inputValue() === 'BSc Computer Science', 'program prefilled');
  check(await page.locator('input[name="contact"]:checked').getAttribute('value') === 'Email', 'contact prefilled');

  // Invalid submit
  await page.locator('#student-id').fill('123');
  await page.locator('button[type="submit"]').click();
  await page.waitForTimeout(150);
  check(await page.locator('#student-id').getAttribute('aria-invalid') === 'true', 'invalid field marked');
  check(await page.locator('#reg-error-summary').isVisible(), 'error summary visible');
  check((await activeInfo()).id === 'reg-error-summary', 'focus on error summary');
  const errText = await page.locator('#student-id-error').innerText();
  check(errText.includes('8 digits') && errText.includes('how') === false && errText.includes('20261457'), 'error text explains fix');
  await page.locator('#reg-error-summary a').click();
  await page.waitForTimeout(100);
  check((await activeInfo()).id === 'student-id', 'error link focuses field');

  // Fix and submit -> dialog
  await page.locator('#student-id').fill('20261457');
  await page.locator('button[type="submit"]').click();
  await page.waitForTimeout(200);
  check(await page.locator('#confirm-dialog').getAttribute('open') !== null, 'dialog opens');
  check((await activeInfo()).id === 'dialog-cancel', 'dialog focuses Cancel');
  check((await page.locator('#dialog-description').innerText()).includes('CSE 320'), 'dialog content names course');
  const dialogName = await page.locator('#confirm-dialog').getAttribute('aria-labelledby');
  check(dialogName === 'dialog-title', 'dialog labelled by title');

  // Cancel with Escape returns focus
  await page.keyboard.press('Escape');
  await page.waitForTimeout(150);
  check(await page.locator('#confirm-dialog').getAttribute('open') === null, 'Escape closes dialog');
  check((await activeInfo()).tag === 'BUTTON' && (await activeInfo()).text === 'Review registration', 'focus returns to opener');

  // Confirm
  await page.locator('button[type="submit"]').click();
  await page.waitForTimeout(150);
  await page.locator('#dialog-confirm').click();
  await page.waitForTimeout(250);
  check(await page.locator('#confirm-dialog').getAttribute('open') === null, 'confirm closes dialog');
  check((await page.locator('.flash').innerText()).includes('Registration saved'), 'save flash shown');
  check((await page.locator('#app-status').innerText()).includes('Registration saved'), 'save announced');
  check((await activeInfo()).tag === 'H1', 'focus moved to new view h1');
  check(await page.locator('.table-scroll tbody tr').count() === 4, 'registered table has 4 rows');

  // Profile
  await page.locator('.nav-list a[data-route="#/profile"]').click();
  await page.waitForTimeout(150);
  check(await page.locator('h1').innerText() === 'Student profile', 'profile loads');
  check(await page.locator('.table-scroll tbody tr').count() === 4, 'profile table 4 rows');
  check(await page.locator('.table-scroll').getAttribute('tabindex') === '0', 'table region focusable');
  check(await page.locator('.table-scroll').getAttribute('role') === 'region', 'table region role');
  check(await page.locator('.table-scroll caption').count() === 1, 'table caption');
  check(await page.locator('.table-scroll th[scope="col"]').count() === 6, '6 column headers');
  check(await page.locator('.table-scroll th[scope="row"]').count() === 4, '4 row headers');
  check(await page.locator('button[aria-label="Drop CSE 320"]').count() === 1, 'drop button named with course');

  // Drop dialog
  await page.locator('button[aria-label="Drop CSE 320"]').click();
  await page.waitForTimeout(150);
  check((await activeInfo()).id === 'dialog-cancel', 'drop dialog focuses Cancel');
  await page.locator('#dialog-confirm').click();
  await page.waitForTimeout(200);
  check((await page.locator('.flash').innerText()).includes('dropped'), 'drop flash shown');
  check(await page.locator('.table-scroll tbody tr').count() === 3, 'profile table back to 3');

  // Focus indicator computed style
  const focusStyle = await page.evaluate(() => {
    const btn = document.querySelector('.nav-list a[data-route="#/home"]');
    btn.focus();
    const cs = getComputedStyle(btn);
    return { outlineWidth: cs.outlineWidth, outlineStyle: cs.outlineStyle, boxShadow: cs.boxShadow };
  });
  check(focusStyle.outlineWidth !== '0px' && focusStyle.outlineStyle !== 'none', 'focus outline present');
  check(focusStyle.boxShadow !== 'none', 'focus ring present');

  // Mobile
  await page.setViewportSize({ width: 320, height: 700 });
  await page.goto('http://localhost:8765/index.html#/catalog');
  await page.waitForTimeout(300);
  const overflow = await page.evaluate(() => ({
    doc: document.documentElement.scrollWidth,
    client: document.documentElement.clientWidth,
    body: document.body.scrollWidth
  }));
  check(overflow.doc <= overflow.client + 1, 'no horizontal page overflow at 320px: ' + JSON.stringify(overflow));
  check(await page.locator('#menu-toggle').isVisible(), 'menu toggle visible at 320px');
  check(await page.locator('#menu-toggle').getAttribute('aria-expanded') === 'false', 'menu starts collapsed');
  check(await page.locator('#primary-nav').isHidden(), 'nav hidden when collapsed');
  await page.locator('#menu-toggle').click();
  await page.waitForTimeout(100);
  check(await page.locator('#menu-toggle').getAttribute('aria-expanded') === 'true', 'menu expands');
  check(await page.locator('#primary-nav').isVisible(), 'nav visible when expanded');
  await page.keyboard.press('Escape');
  await page.waitForTimeout(100);
  check(await page.locator('#menu-toggle').getAttribute('aria-expanded') === 'false', 'Escape collapses menu');
  check((await activeInfo()).id === 'menu-toggle', 'Escape returns focus to toggle');

  // Mobile table scroll region
  await page.goto('http://localhost:8765/index.html#/profile');
  await page.waitForTimeout(300);
  const tableInfo = await page.evaluate(() => {
    const wrap = document.querySelector('.table-scroll');
    return { scrollWidth: wrap.scrollWidth, clientWidth: wrap.clientWidth, overflowX: getComputedStyle(wrap).overflowX };
  });
  check(tableInfo.scrollWidth > tableInfo.clientWidth, 'table scrolls inside container at 320px');
  check(tableInfo.overflowX === 'auto', 'table wrapper overflow auto');
  const mobileOverflow = await page.evaluate(() => document.documentElement.scrollWidth <= document.documentElement.clientWidth + 1);
  check(mobileOverflow, 'profile has no horizontal page overflow at 320px');

  // 200% zoom approximation: 640 CSS px viewport with device scale? use setViewportSize 640
  await page.setViewportSize({ width: 640, height: 700 });
  await page.waitForTimeout(100);
  check(await page.evaluate(() => document.documentElement.scrollWidth <= document.documentElement.clientWidth + 1), 'no overflow at 640px');

  check(consoleErrors.length === 0, 'no console errors: ' + consoleErrors.join(' | '));
  check(pageErrors.length === 0, 'no page errors: ' + pageErrors.join(' | '));

  await page.setViewportSize({ width: 1280, height: 900 });
  await page.goto('http://localhost:8765/index.html#/home');
  await page.waitForTimeout(300);
  await page.screenshot({ path: '/tmp/a11y-test/home.png', fullPage: true });
  await page.goto('http://localhost:8765/index.html#/catalog');
  await page.waitForTimeout(300);
  await page.screenshot({ path: '/tmp/a11y-test/catalog.png', fullPage: true });
  await page.goto('http://localhost:8765/index.html#/register');
  await page.waitForTimeout(300);
  await page.screenshot({ path: '/tmp/a11y-test/register.png', fullPage: true });
  await page.goto('http://localhost:8765/index.html#/profile');
  await page.waitForTimeout(300);
  await page.screenshot({ path: '/tmp/a11y-test/profile.png', fullPage: true });
  await page.setViewportSize({ width: 320, height: 700 });
  await page.goto('http://localhost:8765/index.html#/catalog');
  await page.waitForTimeout(300);
  await page.screenshot({ path: '/tmp/a11y-test/catalog-mobile.png', fullPage: true });

  console.log(failures === 0 ? 'ALL BROWSER TESTS PASSED' : failures + ' FAILURES');
  await browser.close();
})();
EOF
