const { chromium } = require('playwright');
const path = require('path');
const axePath = require.resolve('axe-core/axe.min.js');

(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage({ viewport: { width: 1280, height: 900 } });
  const errors = [];
  page.on('console', m => { if (m.type() === 'error') errors.push(m.text()); });
  page.on('pageerror', e => errors.push(e.message));

  async function scan(label) {
    await page.addScriptTag({ path: axePath });
    const result = await page.evaluate(async () => {
      return await axe.run(document, {
        runOnly: { type: 'tag', values: ['wcag2a', 'wcag2aa', 'wcag21a', 'wcag21aa', 'wcag22aa', 'best-practice'] }
      });
    });
    const violations = result.violations.filter(v => v.impact !== 'minor' || true);
    console.log('\n=== ' + label + ' ===');
    if (violations.length === 0) console.log('No violations');
    for (const v of violations) {
      console.log('[' + v.impact + '] ' + v.id + ': ' + v.help);
      for (const node of v.nodes) {
        console.log('  target: ' + node.target.join(' '));
        console.log('  ' + node.failureSummary.replace(/\n/g, '\n  '));
      }
    }
    return violations.length;
  }

  let total = 0;
  for (const route of ['#/home', '#/catalog', '#/register', '#/profile']) {
    await page.goto('http://localhost:8765/index.html' + route);
    await page.waitForTimeout(400);
    total += await scan(route);
  }

  // Dialog state
  await page.goto('http://localhost:8765/index.html#/register');
  await page.waitForTimeout(300);
  await page.selectOption('#course', 'CSE320');
  await page.locator('button[type="submit"]').click();
  await page.waitForTimeout(200);
  total += await scan('registration dialog');

  // Error state
  await page.goto('http://localhost:8765/index.html#/register');
  await page.waitForTimeout(300);
  await page.locator('#student-id').fill('abc');
  await page.locator('button[type="submit"]').click();
  await page.waitForTimeout(200);
  total += await scan('registration errors');

  // Mobile menu open
  await page.setViewportSize({ width: 320, height: 700 });
  await page.goto('http://localhost:8765/index.html#/catalog');
  await page.waitForTimeout(300);
  await page.locator('#menu-toggle').click();
  await page.waitForTimeout(100);
  total += await scan('mobile menu open');

  console.log('\nTOTAL VIOLATIONS: ' + total);
  console.log('JS ERRORS: ' + (errors.length ? errors.join(' | ') : 'none'));
  await browser.close();
})();
EOF
