  await page.keyboard.press('Tab');
  await page.keyboard.press('Tab'); // Student profile
  await page.keyboard.press('Tab'); // leave nav -> main search
  await page.waitForTimeout(100);
  const expanded = await page.locator('#menu-toggle').getAttribute('aria-expanded');
  check(expanded === 'false', 'menu closes when focus leaves nav');
  const active = await page.evaluate(() => ({ tag: document.activeElement.tagName, id: document.activeElement.id }));
  check(active.id === 'course-search', 'focus continues into main after menu closes: ' + JSON.stringify(active));

  // Mobile registration page overflow
  await page.goto('http://localhost:8765/index.html#/register');
  await page.waitForTimeout(250);
  check(await page.evaluate(() => document.documentElement.scrollWidth <= document.documentElement.clientWidth + 1), 'register no horizontal overflow at 320');
  await page.screenshot({ path: '/tmp/a11y-test/register-mobile.png', fullPage: false });

  check(errs.length === 0, 'no JS errors: ' + errs.join(' | '));
  console.log(fail === 0 ? 'EXTRA TESTS PASSED' : fail + ' FAILURES');
  await browser.close();
})();
EOF
